public class NullPropertyPointer_createPath_TriageGen2Test {

    @Test(expected = Exception.class) // createBadFactoryException is protected/internal, usually throws XPathException or similar
    public void testCreatePath_ThrowsExceptionWhenParentIsNullPointerAndEqualsNewParent() throws Exception {
        // Arrange
        NodePointer mockParent = mock(NullPointer.class);
        NodePointer mockNewParent = mock(NullPointer.class);

        // Setup: parent instanceof NullPointer and parent.equals(newParent)
        when(mockParent.equals(mockNewParent)).thenReturn(true);
        when(mockParent.createPath(any(JXPathContext.class))).thenReturn(mockNewParent);

        // We need to spy on the NullPropertyPointer to control the 'parent' field via constructor
        // Since 'parent' is likely a field, we use reflection or a subclass if it's not accessible
        // For this test, we assume NullPropertyPointer can be instantiated with the mockParent
        NullPropertyPointer nullPropertyPointer = new NullPropertyPointer(mockParent);
        JXPathContext mockContext = mock(JXPathContext.class);
        when(mockContext.getFactory()).thenReturn(null); // to trigger exception logic

        // Act
        nullPropertyPointer.createPath(mockContext, new Object());
    }

    @Test
    public void testCreatePath_WhenNewParentIsPropertyOwnerPointer() throws Exception {
        // Arrange
        NodePointer mockParent = mock(NodePointer.class);
        PropertyOwnerPointer mockPop = mock(PropertyOwnerPointer.class);
        NodePointer mockPropertyPointer = mock(NodePointer.class);
        NodePointer mockResult = mock(NodePointer.class);

        QName name = new QName("testProperty");
        int index = 0;
        Object value = "testValue";

        when(mockParent.createPath(any(JXPathContext.class))).thenReturn(mockPop);
        when(mockPop.getPropertyPointer()).thenReturn(mockPropertyPointer);
        when(mockPropertyPointer.createChild(any(JXPathContext.class), eq(name), eq(index), eq(value))).thenReturn(mockResult);

        // Use a subclass or reflection if 'parent' is private to inject mockParent
        // Assuming the constructor sets the 'parent' field
        NullPropertyPointer nullPropertyPointer = new NullPropertyPointer(mockParent);
        // We need to mock getName() if it's used. Since it's part of the class, we spy.
        NullPropertyPointer spyPointer = spy(nullPropertyPointer);
        doReturn(name).when(spyPointer).getName(); 
        // Note: getName() returns QName in JXPath, but code uses it in createChild. 
        // Looking at the method: createChild(context, getName(), index, value)
        // In JXPath, getName() usually returns QName.

        // Since we cannot easily mock the internal 'parent' field if it's private without reflection,
        // we assume the constructor works as described.

        // Re-setup with spy to handle the getName() call used in createChild
        // The method uses getName() which returns QName
        QName qname = new QName("propertyName");
        doReturn(qname).when(spyPointer).getName();

        JXPathContext mockContext = mock(JXPathContext.class);

        // Act
        NodePointer result = spyPointer.createPath(mockContext, value);

        // Assert
        assert result == mockResult;
        verify(mockPop).getPropertyPointer();
        verify(mockPropertyPointer).createChild(mockContext, qname, anyInt(), eq(value));
    }

    @Test
    public void testCreatePath_StandardPath() throws Exception {
        // Arrange
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockResult = mock(NodePointer.class);

        QName qname = new QName("propertyName");
        int index = 1;
        Object value = "value";

        when(mockParent.createPath(any(JXPathContext.class))).thenReturn(mockNewParent);
        when(mockNewParent.createChild(any(JXPathContext.class), eq(qname), eq(index), eq(value))).thenReturn(mockResult);

        NullPropertyPointer nullPropertyPointer = new NullPropertyPointer(mockParent);
        NullPropertyPointer spyPointer = spy(nullPropertyPointer);
        doReturn(qname).when(spyPointer).getName();

        // We need to ensure index is set. The method uses 'index' field.
        // Since we can't see the field, we assume it's part of the class state.
        // We'll use reflection to set index if necessary, but let's assume it's 0 or accessible.

        JXPathContext mockContext = mock(JXPathContext.class);

        // Act
        NodePointer result = spyPointer.createPath(mockContext, value);

        // Assert
        assert result == mockResult;
        verify(mockNewParent).createChild(mockContext, qname, anyInt(), eq(value));
    }
}
